#include <iostream>

long long power(int base, int exponent)
{
    long long result{ 1 };

    for (int i = 0; i < exponent; ++i)
    {
        result *= base;
    }

    return result;
}

int main()
{
    int base{};
    int exponent{};
    if (!(std::cin >> base >> exponent)) return 0;

    std::cout << "square " << power(base, 2) << "\n";
    std::cout << "power " << power(base, exponent) << "\n";

    return 0;
}

