int main()
{
    int a{};
    int b{};
    if (!(std::cin >> a >> b)) return 0;

    int x{ a };
    int y{ b };

    while (y != 0)
    {
        int r{ x % y };
        x = y;
        y = r;
    }

    std::cout << "gcd " << x << "\n";
    std::cout << "lcm " << static_cast<long long>(a / x) * b << "\n";

    return 0;
}

