#include <iostream>
#include <vector>

void extremes(const std::vector<int>& values, int& lowest, int& highest)
{
    (void)lowest;
    (void)highest;

    int lo{ values[0] };
    int hi{ values[0] };

    for (std::size_t i = 1; i < values.size(); ++i)
    {
        if (values[i] < lo) lo = values[i];
        if (values[i] > hi) hi = values[i];
    }

    std::cout << "min " << lo << "\n";
    std::cout << "max " << hi << "\n";
}

int main()
{
    std::vector<int> values{};
    int x{};

    while (std::cin >> x) values.push_back(x);

    if (values.empty())
    {
        std::cout << "empty\n";
        return 0;
    }

    int lowest{};
    int highest{};
    extremes(values, lowest, highest);

    return 0;
}

