#include <iomanip>
#include <iostream>
#include <vector>

int main()
{
    std::vector<int> values{};
    int x{};
    int total{};

    while (std::cin >> x)
    {
        values.push_back(x);
        total += x;
    }

    if (values.empty())
    {
        std::cout << "mean none\n";
        std::cout << "above 0\n";
        return 0;
    }

    double mean{ static_cast<double>(total) / static_cast<double>(values.size()) };

    int above{};
    for (int value : values)
    {
        if (value > mean) ++above;
    }

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "mean " << mean << "\n";
    std::cout << "above " << above << "\n";

    return 0;
}
